```csharp
namespace TOLIK.Infrastructure.Authorization;

/// <summary>
/// Role model and authorization ceilings (stage 2 port of interface/policy.js
/// ROLE_RISK_CEILING, adapted to the normative matrix in docs/authorization.md):
/// a role's ceiling is the maximum effective risk (max(declared, escalated)) that
/// role may ever be authorized for. Escalation raises risk toward the ceiling;
/// the ceiling itself can never be raised by confirmation or MFA.
/// Unknown/unresolvable roles have no ceiling — fail closed (deny everything).
/// </summary>
public static class AuthorizationRoles
{
    public const string Owner = "Owner";
    public const string AuthorizedUser = "AuthorizedUser";
    public const string Guest = "Guest";

    /// <summary>Resolves a stored role string to the contract enum; false for unknown roles (fail closed).</summary>
    public static bool TryResolve(string? role, out IdentityRole resolved)
    {
        switch (role)
        {
            case Owner: resolved = IdentityRole.Owner; return true;
            case AuthorizedUser: resolved = IdentityRole.AuthorizedUser; return true;
            case Guest: resolved = IdentityRole.Guest; return true;
            default: resolved = default; return false;
        }
    }

    /// <summary>
    /// Maximum effective risk the role may be authorized for (ROLE_RISK_CEILING).
    /// Null = no ceiling = nothing is authorized for this role (Guest per docs/authorization.md).
    /// </summary>
    public static ToolRiskLevel? CeilingFor(string? role) => role switch
    {
        Owner => ToolRiskLevel.Critical,
        AuthorizedUser => ToolRiskLevel.Destructive,
        _ => null, // Guest and unknown roles: always denied (fail closed)
    };

    /// <summary>Owner-role gate used by owner-only endpoints (confirmation approval, full audit view).</summary>
    public static bool IsOwner(string? role) => string.Equals(role, Owner, StringComparison.Ordinal);
}
```

