namespace TOLIK.Infrastructure.Authorization;

/// <summary>
/// Role model and per-role authorization ceilings (stage 2 port of the browser
/// reference ROLE_RISK_CEILING, interface/policy.js; backlog item in
/// docs/INTERFACE-ANALYSIS.md). A role's ceiling is the maximum EFFECTIVE risk
/// (max(declared, escalated)) that role may ever be authorized for: escalation
/// raises risk toward the ceiling, and no confirmation or MFA can raise the
/// ceiling itself. Fail closed: unknown/unresolvable roles have no ceiling and
/// authorize nothing.
/// </summary>
public static class AuthorizationRoles
{
    public const string Owner = "Owner";
    public const string AuthorizedUser = "AuthorizedUser";
    public const string Guest = "Guest";

    /// <summary>
    /// Resolves a stored role string to the contract enum. False for unknown roles —
    /// fail closed (an unrecognized role can never authorize execution).
    /// </summary>
    public static bool TryResolve(string? role, out IdentityRole resolved) { ... }

    /// <summary>
    /// Maximum effective risk the role may be authorized for; null = no ceiling =
    /// nothing is authorized (Guest per docs/authorization.md; Unknown per reference).
    /// Aligned to the normative matrix: HIGH (Modify/Destructive) allows
    /// Owner/AuthorizedUser, CRITICAL requires Owner.
    /// </summary>
    public static ToolRiskLevel? CeilingFor(string? role) => role switch
    {
        Owner => ToolRiskLevel.Critical,
        AuthorizedUser => ToolRiskLevel.Destructive,
        _ => null,
    };

    /// <summary>Owner-only gate (confirmation approval, full audit view) — one place for the role semantics.</summary>
    public static bool IsOwner(string? role) => string.Equals(role, Owner, StringComparison.Ordinal);
}
```

