namespace TOLIK.Infrastructure.Authorization;

/// <summary>
/// Role model and per-role authorization ceilings — stage 2 of the interface/ port
/// (ROLE_RISK_CEILING in the browser reference policy.js; backlog item in
/// docs/INTERFACE-ANALYSIS.md). A role's ceiling is the maximum EFFECTIVE risk
/// (max(declared, escalated)) that role may ever be authorized for: escalation
/// raises risk toward the ceiling, and neither confirmation nor MFA can raise the
/// ceiling itself — exceeding it is a hard Deny (fail closed, never
/// ConfirmationRequired). Ceiling values follow the normative matrix in
/// docs/authorization.md: HIGH (Modify/Destructive) allows Owner/AuthorizedUser,
/// CRITICAL requires Owner, Guest is always denied. The reference roles
/// TrustedGuest/Family have no enrollment path yet; they resolve to no ceiling
/// and stay denied until enrollment lands.
/// </summary>
public static class AuthorizationRoles
{
    /// <summary>Canonical role strings as stored in TolikUser.Role — one place for role semantics.</summary>
    public const string Owner = "Owner";
    public const string AuthorizedUser = "AuthorizedUser";
    public const string Guest = "Guest";

    /// <summary>
    /// Maximum effective risk the role may be authorized for (ROLE_RISK_CEILING).
    /// Null = no ceiling: nothing is authorized for this role (fail closed) —
    /// Guest per docs/authorization.md, any unrecognized string likewise.
    /// </summary>
    public static ToolRiskLevel? CeilingFor(string? role) => role switch
    {
        Owner => ToolRiskLevel.Critical,
        AuthorizedUser => ToolRiskLevel.Destructive,
        _ => null
    };

    /// <summary>Owner-only gate (confirmation approval, full audit view) — exact ordinal match.</summary>
    public static bool IsOwner(string? role) => string.Equals(role, Owner, StringComparison.Ordinal);
}
"}

