{"file_path":"C:\DEV\TOLIK_Harness\tests\TOLIK.Foundation.Tests\RoleCeilingTests.cs","content":"using TOLIK.Contracts;
using TOLIK.Infrastructure.Authorization;
using TOLIK.Infrastructure.Identity;

namespace TOLIK.Foundation.Tests;

/// <summary>
/// Roles and authorization ceilings (stage 2 of the interface/ port, ROLE_RISK_CEILING):
/// a role's ceiling is the maximum effective risk it may ever be authorized for.
/// Escalation raises risk toward the ceiling; confirmation and MFA can never raise
/// the ceiling. Fail closed: roles without a ceiling authorize nothing.
/// </summary>
public sealed class RoleCeilingTests
{
    private static AuthorizationRequest Request(
        string? role,
        AgentCapability capability,
        ToolRiskLevel declared,
        string resource,
        bool confirmation = false,
        bool mfa = false) => new(
        Principal: new SessionPrincipal(Guid.NewGuid(), Guid.NewGuid(), Guid.NewGuid(), role!),
        Capability: capability,
        Risk: declared,
        Resource: resource,
        AllowedResource: resource,
        ConfirmationValid: confirmation,
        MfaValid: mfa);

    // --- ceiling table (docs/authorization.md normative matrix) ---

    [Fact]
    public void Ceiling_table_matches_normative_matrix()
    {
        Assert.Equal(ToolRiskLevel.Critical, AuthorizationRoles.CeilingFor("Owner"));
        Assert.Equal(ToolRiskLevel.Destructive, AuthorizationRoles.CeilingFor("AuthorizedUser"));
        Assert.Null(AuthorizationRoles.CeilingFor("Guest"));
        // Reference roles without a .NET enrollment path resolve to no ceiling.
        Assert.Null(AuthorizationRoles.CeilingFor("TrustedGuest"));
        Assert.Null(AuthorizationRoles.CeilingFor("Family"));
        // Unrecognized, empty and missing roles fail closed.
        Assert.Null(AuthorizationRoles.CeilingFor("Superuser"));
        Assert.Null(AuthorizationRoles.CeilingFor("owner"));
        Assert.Null(AuthorizationRoles.CeilingFor(""));
        Assert.Null(AuthorizationRoles.CeilingFor(null));
    }

    [Fact]
    public void Owner_gate_is_exact_ordinal_match()
    {
        Assert.True(AuthorizationRoles.IsOwner("Owner"));
        Assert.False(AuthorizationRoles.IsOwner("owner"));
        Assert.False(AuthorizationRoles.IsOwner("AuthorizedUser"));
        Assert.False(AuthorizationRoles.IsOwner("Owner "));
        Assert.False(AuthorizationRoles.IsOwner(""));
        Assert.False(AuthorizationRoles.IsOwner(null));
    }

    // --- fail-closed denial cases ---

    [Fact]
    public void Unknown_role_denies_even_read_only()
    {
        Assert.Equal(AuthorizationDecision.Deny,
            AuthorizationPolicy.Evaluate(Request("Superuser", AgentCapability.ReadFile, ToolRiskLevel.ReadOnly, "project-a")));
        Assert.Equal(AuthorizationDecision.Deny,
            AuthorizationPolicy.Evaluate(Request("", AgentCapability.ReadFile, ToolRiskLevel.ReadOnly, "project-a")));
    }

    [Fact]
    public void Guest_denies_everything_including_read_only()
    {
        Assert.Equal(AuthorizationDecision.Deny,
            AuthorizationPolicy.Evaluate(Request("Guest", AgentCapability.ReadFile, ToolRiskLevel.ReadOnly, "project-a")));
        Assert.Equal(AuthorizationDecision.Deny,
            AuthorizationPolicy.Evaluate(Request("Guest", AgentCapability.WriteFile, ToolRiskLevel.Modify, "project-a", confirmation: true)));
    }

    [Fact]
    public void AuthorizedUser_cannot_reach_critical_even_with_mfa_and_confirmation()
    {
        // Normative matrix: CRITICAL requires Owner. The ceiling is the enforcement:
        // no confirmation or MFA combination raises an AuthorizedUser's ceiling.
        var request = Request("AuthorizedUser", AgentCapability.WriteFile, ToolRiskLevel.Critical, "project-a", confirmation: true, mfa: true);
        Assert.Equal(AuthorizationDecision.Deny, AuthorizationPolicy.Evaluate(request));
    }

    [Fact]
    public void AuthorizedUser_ceiling_blocks_escalated_critical_write()
    {
        // WriteFile onto a security-critical source escalates to Critical, which is
        // above the AuthorizedUser ceiling (Destructive) — denied even with confirmation.
        var decision = AuthorizationPolicy.Evaluate(Request(
            "AuthorizedUser", AgentCapability.WriteFile, ToolRiskLevel.Modify,
            "src/TOLIK.Infrastructure/Authorization/AuthorizationPolicy.cs", confirmation: true));
        Assert.Equal(AuthorizationDecision.Deny, decision);
    }

    [Fact]
    public void Ceiling_denial_is_deny_never_confirmation_required()
    {
        // A ceiling can never be satisfied by a confirmation: without one the decision
        // must still be a hard Deny, so the step fails instead of parking forever.
        var decision = AuthorizationPolicy.Evaluate(Request(
            "AuthorizedUser", AgentCapability.WriteFile, ToolRiskLevel.Modify,
            "src/TOLIK.Infrastructure/Authorization/AuthorizationPolicy.cs", confirmation: false));
        Assert.Equal(AuthorizationDecision.Deny, decision);
    }

    // --- ceilings must not weaken existing grants ---

    [Fact]
    public void Owner_still_reaches_critical_escalated_write_with_mfa_and_confirmation()
    {
        // Same request as the AuthorizedUser variant above — the Owner ceiling
        // (Critical) must keep the existing escalation path intact.
        var decision = AuthorizationPolicy.Evaluate(Request(
            "Owner", AgentCapability.WriteFile, ToolRiskLevel.Modify,
            "src/TOLIK.Infrastructure/Authorization/AuthorizationPolicy.cs", confirmation: true, mfa: true));
        Assert.Equal(AuthorizationDecision.Allow, decision);
    }

    [Fact]
    public void AuthorizedUser_within_ceiling_allows_low_and_high_categories_with_confirmation()
    {
        // LOW stays available without confirmation.
        Assert.Equal(AuthorizationDecision.Allow,
            AuthorizationPolicy.Evaluate(Request("AuthorizedUser", AgentCapability.ReadFile, ToolRiskLevel.ReadOnly, "project-a")));
        // HIGH (Modify/Destructive) stays available with confirmation — the ceiling is
        // inclusive at Destructive, including an escalation TO Destructive.
        Assert.Equal(AuthorizationDecision.Allow,
            AuthorizationPolicy.Evaluate(Request("AuthorizedUser", AgentCapability.WriteFile, ToolRiskLevel.Modify, "project-a", confirmation: true)));
        Assert.Equal(AuthorizationDecision.Allow,
            AuthorizationPolicy.Evaluate(Request("AuthorizedUser", AgentCapability.WriteFile, ToolRiskLevel.Destructive, "project-a", confirmation: true)));
        Assert.Equal(AuthorizationDecision.Allow,
            AuthorizationPolicy.Evaluate(Request("AuthorizedUser", AgentCapability.WriteFile, ToolRiskLevel.LowRisk, "repo/.git/hooks/pre-commit", confirmation: true)));
    }

    [Fact]
    public void Owner_read_only_and_modify_paths_unchanged_by_ceilings()
    {
        Assert.Equal(AuthorizationDecision.Allow,
            AuthorizationPolicy.Evaluate(Request("Owner", AgentCapability.ReadFile, ToolRiskLevel.ReadOnly, "project-a")));
        Assert.Equal(AuthorizationDecision.Allow,
            AuthorizationPolicy.Evaluate(Request("Owner", AgentCapability.WriteFile, ToolRiskLevel.Modify, "project-a", confirmation: true)));
        Assert.Equal(AuthorizationDecision.ConfirmationRequired,
            AuthorizationPolicy.Evaluate(Request("Owner", AgentCapability.WriteFile, ToolRiskLevel.Destructive, "project-a", confirmation: false)));
    }

    // --- transport authorization inherits ceilings (defense in depth) ---

    [Fact]
    public void Transport_authorization_applies_ceiling_to_role()
    {
        var agent = Guid.NewGuid();
        var registration = new AgentRegistration(agent, ImmutableHashSet.Create(AgentCapability.WriteFile));

        // Declared Critical is above the AuthorizedUser ceiling — denied by the
        // ceiling gate even though all transport-level gates pass.
        var criticalCommand = new AgentCommand(Guid.NewGuid(), AgentCapability.WriteFile, ToolRiskLevel.Critical, ImmutableDictionary<string, string>.Empty);
        var authorizedUser = new SessionPrincipal(Guid.NewGuid(), Guid.NewGuid(), Guid.NewGuid(), "AuthorizedUser");
        Assert.Equal(AuthorizationDecision.Deny,
            AgentTransportAuthorization.Evaluate(new(authorizedUser, agent, registration, criticalCommand)));

        // Declared Modify is within the ceiling — not denied by the ceiling (transport
        // has no confirmation, so the risk switch yields ConfirmationRequired).
        var modifyCommand = new AgentCommand(Guid.NewGuid(), AgentCapability.WriteFile, ToolRiskLevel.Modify, ImmutableDictionary<string, string>.Empty);
        Assert.Equal(AuthorizationDecision.ConfirmationRequired,
            AgentTransportAuthorization.Evaluate(new(authorizedUser, agent, registration, modifyCommand)));
    }
}
"}

