/// <summary>
/// Role ceilings end-to-end (stage 2 of the interface/ port): a role's ceiling is
/// enforced through the real HTTP chain (authentication → authorization), not only
/// in the pure policy function. AuthorizedUser/Guest/unknown sessions are minted
/// directly (no enrollment path for non-Owner roles exists yet).
/// </summary>
public sealed class RoleCeilingIntegrationTests
{
    private static async Task<string> MintSessionAsync(CoreHostFactory factory, string role)
    {
        await using var db = await factory.Services.GetRequiredService<IDbContextFactory<TolikDbContext>>().CreateDbContextAsync();
        var now = DateTimeOffset.UtcNow;
        var token = Convert.ToBase64String(RandomNumberGenerator.GetBytes(32));
        var user = new TolikUser { Id = Guid.NewGuid(), Role = role, CreatedAt = now };
        var device = new TolikDevice { Id = Guid.NewGuid(), UserId = user.Id, InstallationId = "ceiling-test", PublicKey = "test-key", CreatedAt = now };
        var session = new TolikSession { Id = Guid.NewGuid(), UserId = user.Id, DeviceId = device.Id, TokenHash = IdentityService.HashToken(token), CreatedAt = now, ExpiresAt = now.AddMinutes(30) };
        db.AddRange(user, device, session);
        await db.SaveChangesAsync();
        return token;
    }

    [Fact]
    public async Task AuthorizedUser_within_ceiling_creates_task_and_gets_accepted()
    {
        using var factory = new CoreHostFactory();
        using var client = factory.CreateClient();

        var sessionToken = await MintSessionAsync(factory, "AuthorizedUser");
        client.DefaultRequestHeaders.Authorization = new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", sessionToken);

        // RunBuild (LowRisk) is within the AuthorizedUser ceiling — LOW/MEDIUM
